<script setup lang="ts">
import {computed,defineAsyncComponent,ref} from 'vue'
import {Clock3,LoaderCircle,ShieldCheck,CheckCircle2,AlertCircle,XCircle,Copy,Check,Wallet,History,Mail} from 'lucide-vue-next'
import {cash,date,type Row} from '../lib'
const AdminRefundTimeline=defineAsyncComponent(()=>import('./AdminRefundTimeline.vue'))
const props=defineProps<{detail:Row;admin?:boolean}>()
const order=computed(()=>props.detail.order),copied=ref(false),copyError=ref('')
const states:Row={queued:{label:'排队中',icon:Clock3,tone:'pending'},processing:{label:'办理中',icon:LoaderCircle,tone:'active'},verifying:{label:'核实中',icon:ShieldCheck,tone:'active'},attention:{label:'待跟进',icon:AlertCircle,tone:'attention'},succeeded:{label:'服务已完成',icon:CheckCircle2,tone:'success'},failed:{label:'办理失败',icon:XCircle,tone:'failed'},banned:{label:'账号不可用',icon:AlertCircle,tone:'failed'},cancelled:{label:'已取消',icon:XCircle,tone:'neutral'}}
const state=computed(()=>states[order.value.status]||{label:'处理中',icon:Clock3,tone:'neutral'})
const fees:Row={frozen:{label:'冻结中',note:'服务费已冻结，完成交付后才结算。'},settled:{label:'已结算',note:'服务已完成，服务费已从冻结积分中扣除。'},released:{label:'已释放',note:'冻结服务费已返还可用余额。'}}
const fee=computed(()=>fees[order.value.fee_status]||{label:'待确认',note:'费用状态以订单记录为准。'})
const events=computed(()=>[...(props.detail.events||[])].sort((a:Row,b:Row)=>new Date(b.created_at).getTime()-new Date(a.created_at).getTime()))
async function copyID(){try{await navigator.clipboard.writeText(order.value.id);copied.value=true;copyError.value=''}catch{copyError.value='复制失败，请手动选择订单号复制。'}}
</script>
<template>
 <div class="refund-detail">
  <section class="refund-detail-status" :class="state.tone" aria-label="当前办理状态">
   <span class="refund-detail-status-icon"><component :is="state.icon" :size="25"/></span>
   <div><span class="refund-detail-kicker">代退申请</span><h3>{{state.label}}</h3><p>{{order.message||'进度更新后会同步显示在这里。'}}</p></div>
   <span class="refund-detail-live" v-if="['queued','processing','verifying'].includes(order.status)"><i/>进度自动更新</span>
  </section>
  <div class="refund-detail-cards">
   <section class="refund-detail-card"><h4><Mail :size="16"/>申请账号</h4><b class="refund-detail-email">{{order.email}}</b><span class="refund-detail-caption">提交时间 · {{date(order.created_at)}}</span><span v-if="admin&&order.user_email" class="refund-detail-caption">申请人 · {{order.user_email}}</span></section>
   <section class="refund-detail-card"><h4><Wallet :size="16"/>服务费用<span class="refund-detail-fee-state" :class="order.fee_status">{{fee.label}}</span></h4><strong class="refund-detail-amount">{{cash(order.fee)}}<small>积分</small></strong><span class="refund-detail-caption">{{fee.note}}</span></section>
  </div>
  <div class="refund-detail-reference"><span>订单编号</span><code>{{order.id}}</code><button class="icon-btn" :aria-label="copied?'订单号已复制':'复制订单号'" @click="copyID"><Check v-if="copied" :size="15"/><Copy v-else :size="15"/></button></div>
  <p v-if="copyError" class="refund-detail-copy-error" role="alert">{{copyError}}</p>
  <AdminRefundTimeline v-if="admin" :id="order.id" :status="order.status"/>
  <section v-if="!admin" class="refund-detail-progress" aria-label="办理动态">
   <div class="refund-detail-section-heading"><h4><History :size="17"/>办理动态</h4><span>最新动态在前</span></div>
   <ol v-if="events.length" class="refund-detail-events"><li v-for="(event,index) in events" :key="event.id||index" :class="{latest:index===0}"><span class="refund-detail-event-dot"/><div><b>{{event.message}}</b><time>{{date(event.created_at)}}</time></div></li></ol>
   <p v-else class="refund-detail-caption refund-detail-empty">暂无办理动态，进度更新后会显示在这里。</p>
  </section>
  <details v-else class="refund-detail-history"><summary>客户可见动态 <span>{{events.length}} 条记录</span></summary><ol class="refund-detail-events"><li v-for="(event,index) in events" :key="event.id||index"><span class="refund-detail-event-dot"/><div><b>{{event.message}}</b><time>{{date(event.created_at)}}</time></div></li></ol><p v-if="!events.length" class="refund-detail-caption">暂无动态</p></details>
  <slot/>
  <p class="refund-detail-note"><ShieldCheck :size="15"/><span>服务完成表示代退流程已完成，实际退款到账以支付渠道记录为准。</span></p>
 </div>
</template>
